from collections import abc
from moler.util.moler_test import MolerTest  # type: ignore
from taf.ul.sc.perf.parsers.file_parser import FileParser
from typing import Dict, Any

_stats: Dict[Any, Any] = {}


def add_stats(stats, print_markers=True, stats_type='marker'):
    """
    Function adds stats to global variable _all_stats.
    Sample markers:
    stats['DB->string properties->build'] = "459"
    stats['DB->string properties->test release'] = "18A"

    :param stats: dictionary of stats. Could be provide as markers or full dictionary stats
    :param print_markers: Flag if print markers to main log
    :param stats_type: marker or dictionary
    :return: None
    """
    if isinstance(stats, dict):
        if stats_type == 'marker':
            convert_string_stats_to_dict(stats, all_stats=get_stats())
            if print_markers:
                _print_stats(stats)
        elif stats_type == 'dictionary':
            merge_dicts(dct=get_stats(), merge_dct=stats)
        else:
            raise ValueError("stats_type should be 'marker' or 'dictionary'")
    else:
        raise TypeError("stats parameter {} is not a dictionary".format(stats))


def get_stats():
    """
    Function return private value _all_stats.

    :return: _stats
    """
    return _stats


def clear_stats():
    """
    Function clears global variable _stats.

    :return: None
    """
    global _stats
    _stats.clear()


def get_markers_from_log_file(file_path):
    """
    Function grabs markers from file and convert to dictionary.

    :param file_path: path to main log
    :return: stats
    """
    stats = {}
    markers_parser = FileParser(file_path=file_path)
    markers_parser.add_parser(name='stats_parser', pattern=r"\[(?P<KEY>DB.*)\] =-> \[(?P<VALUE>.*)\]",
                              callback=_markers_parser_callback,
                              callback_params={'parser': markers_parser, 'stats': stats})
    markers_parser.parsing()
    all_stats = convert_string_stats_to_dict(stats, all_stats={})

    return all_stats


def convert_string_stats_to_dict(stats, all_stats={}):
    """
    Function converts markers to dictionary.

    :param stats: dictionary of markers
    :param all_stats: output dictionary. stats are added to already existing in all_stats
    :return: all_stats
    """
    for string_key in stats:
        single_stats = all_stats
        stats_keys = string_key.split('->')
        keys_number = len(stats_keys)
        for i, stats_key in enumerate(stats_keys):
            if i == (keys_number - 1):
                single_stats[stats_key] = stats[string_key]
            else:
                if stats_key not in single_stats:
                    single_stats[stats_key] = {}

                single_stats = single_stats[stats_key]

    return all_stats


def merge_dicts(dct, merge_dct):
    """ Recursive dict merge. Inspired by :meth:``dict.update()``, instead of
    updating only top-level keys, dict_merge recurses down into dicts nested
    to an arbitrary depth, updating keys. The ``merge_dct`` is merged into
    ``dct``.
    :param dct: dict onto which the merge is executed
    :param merge_dct: dct merged into dct
    :return: None
    """
    for k, v in merge_dct.items():
        if (k in dct and isinstance(dct[k], dict)
                and isinstance(merge_dct[k], abc.Mapping)):
            merge_dicts(dct[k], merge_dct[k])
        else:
            dct[k] = merge_dct[k]


def _print_stats(stats):
    """
    Prints markers.

    :param stats: dictionary with markers
    :return: None
    """
    for key in stats:
        MolerTest.info("")
        MolerTest.info("% [{}] =-> [{}]".format(key, stats[key]))


def _markers_parser_callback(parser, stats):
    """
    Adds caught marker to stats dictionary.

    :param parser: FileParser object
    :param stats: dictionary.
    :return: None
    """
    key = parser.last_matched['named_groups']['KEY']
    value = parser.last_matched['named_groups']['VALUE']
    stats[key] = value
